  const handleSpatialNavigate = useCallback((direction: string) => {
    const activeId = quickLookItem?.id || (selection.length === 1 ? selection[0] : null);
    if (!activeId) return;
    const current = items.find(i => i.id === activeId); if (!current) return;
    const candidates = items.filter(i => { if (i.id === activeId || i.type === ItemType.FRAME || !i.content) return false; const cx = i.x + i.width/2, cy = i.y + i.height/2; const curX = current.x + current.width/2, curY = current.y + current.height/2; if (direction === 'ArrowRight') return cx > curX + 10; if (direction === 'ArrowLeft') return cx < curX - 10; if (direction === 'ArrowUp') return cy < curY - 10; if (direction === 'ArrowDown') return cy > curY + 10; return false; });
    const next = candidates.sort((a, b) => { const curX = current.x + current.width/2, curY = current.y + current.height/2; const da = Math.hypot((a.x + a.width/2) - curX, (a.y + a.height/2) - curY); const db = Math.hypot((b.x + b.width/2) - curX, (b.y + b.height/2) - curY); return da - db; })[0];
    if (next) { 
        if (quickLookItem) setQuickLookItem(next); 
        else { 
            setSelection([next.id]); 
            centerOnItem(next); 
        } 
    }
  }, [items, quickLookItem, selection, centerOnItem]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement; if (target.tagName?.toUpperCase() === 'INPUT' || target.tagName?.toUpperCase() === 'TEXTAREA' || target.isContentEditable) return;
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') { e.preventDefault(); if (e.shiftKey) redo(); else undo(); return; }
      if (e.key === 'Delete' || e.key === 'Backspace') { if (selection.length > 0) handleDeleteItems(selection); }
      if (e.key === ' ') { e.preventDefault(); if (quickLookItem) setQuickLookItem(null); else if (selectedItem) setQuickLookItem(selectedItem); }
      if (e.key === 'Escape') { if (quickLookItem) setQuickLookItem(null); else if (editMode) setEditMode(false); else if (isPickingPoint) setIsPickingPoint(false); setExpressionState({ itemId: '', isOpen: false }); setInferenceState({ itemId: '', isOpen: false }); setTool('select'); }
      if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) { e.preventDefault(); if (quickLookItem || selection.length === 1) { handleSpatialNavigate(e.key); } else if (selection.length > 0) { const step = e.shiftKey ? 10 : 1; const updates = selection.map(id => { const item = items.find(i => i.id === id); if (!item) return null; let nx = item.x, ny = item.y; if (e.key === 'ArrowUp') ny -= step; if (e.key === 'ArrowDown') ny += step; if (e.key === 'ArrowLeft') nx -= step; if (e.key === 'ArrowRight') nx += step; return { id, updates: { x: nx, y: ny } }; }).filter(Boolean) as { id: string, updates: Partial<CanvasItem> }[]; if (updates.length > 0) { handleUpdateItems(updates); commit(items.map(it => { const upd = updates.find(u => u.id === it.id); return upd ? { ...it, ...upd.updates } : it; })); } } }
      if (e.key.toLowerCase() === 'v') setTool('select');
      if (e.key.toLowerCase() === 'h') setTool('hand');
      if (e.key.toLowerCase() === 'r') setTool('point');
      if (e.key.toLowerCase() === 'c') setTool('capture');
      if (e.key.toLowerCase() === 'g') setShowGrid(prev => !prev);
      if (e.key.toLowerCase() === 't') setTool('text');
    };
    window.addEventListener('paste', handlePaste); window.addEventListener('keydown', handleKeyDown); 
    return () => { window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('paste', handlePaste); };
  }, [selection, items, redo, undo, commit, editMode, quickLookItem, selectedItem, handleSpatialNavigate, isPickingPoint, handlePaste]);

  const startRecording = async (resolution: string) => {
