// 识别特定坐标点的特征名称
export const identifyPoint = async (base64: string, y: number, x: number): Promise<string> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType } },
                    { text: `观察归一化坐标 [y=${Math.round(y)}, x=${Math.round(x)}]。请仅返回该处的视觉特征中文名称，控制在 6 字以内。` }
                ]
            }]
        });
        return response.text?.trim() || "选定点位";
    });
};

// 自动识别图中所有关键视觉点位（解构模式）
export const detectAllPoints = async (base64: string, temperature: number = 0.8): Promise<{point: [number, number], label: string}[]> => {
    return retryWithBackoff(async () => {
        const ai = getAI();
        const data = base64.split(',')[1] || base64;
        const mimeType = base64.split(';')[0].split(':')[1] || 'image/jpeg';

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: [{
                parts: [
                    { inlineData: { data, mimeType } },
                    { text: `识别图中所有关键视觉特征. 必须包含：1.主体大特征；2.细节特征。返回 JSON 数组，包含 'point' [y, x] 坐标 (0-1000) 和 'label' 描述。` }
                ]
            }],
            config: { 
                responseMimeType: "application/json",
                temperature: temperature, // 解析强度
                responseSchema: {
                    type: Type.ARRAY,
                    items: {
                        type: Type.OBJECT,
                        properties: {
                            point: { type: Type.ARRAY, items: { type: Type.NUMBER } },
                            label: { type: Type.STRING }
                        },
                        required: ["point", "label"]
                    }
                }
            }
        });
        return JSON.parse(response.text);
    });
};
