                }
                url = await generateWithReferences(task.prompt, refs, ratioToUse, styleObj.promptSuffix, currentArtisticLevel, resolution, settings?.spatialConfig || contextItem.spatialConfig, recipeTxt, undefined, usePro); 
            }
            else if (manualRefs && manualRefs.length > 0) { 
