    const children = items.filter(it => 
        it.id !== frame.id && it.type === ItemType.IMAGE && it.content &&
        (it.x + it.width/2) >= frame.x && (it.x + it.width/2) <= frame.x + frame.width && 
        (it.y + it.height/2) >= frame.y && (it.y + it.height/2) <= frame.y + frame.height
    );

    if (action === 'merge') {
        if (children.length === 0) { alert("画框内没有可融合的图像。"); return; }
        const refs = children.map((c, nid) => ({ label: `Subject ${nid + 1}`, base64: c.content }));
        const prompt = frame.prompt || "Seamless scene integration with consistent lighting and shadows.";
