  const handleFloatingAction = async (id: string, action: string) => {
    const currentSelectedItems = items.filter(i => selection.includes(i.id)); 
    const firstItem = currentSelectedItems[0]; if (!firstItem) return;

    if (action.startsWith('expr:')) { 
      handleGenerate(firstItem.id, `Change to ${action.split(':')[1]}`); 
      setExpressionState({ itemId: '', isOpen: false });
      return; 
    }
    if (action.startsWith('inference:')) { 
      handleGenerate(firstItem.id, `inference:${action.split(':')[1]}`); 
      setInferenceState({ itemId: '', isOpen: false });
      return; 
    }
    if (action.startsWith('evolve_with_level:')) { 
      const level = parseInt(action.split(':')[1]); setCurrentEvolutionLevel(level); 
      handleGenerate(firstItem.id, `__EVOLUTION__|${level}${isCncMode ? '|CNC' : ''}`); 
      setExpressionState({ itemId: '', isOpen: false });
      return; 
    }

    if (action.startsWith('model_cmd:')) {
        const fullCmd = action.split(':')[1].trim();
        const cmd = fullCmd.toLowerCase();

        if (cmd.includes('爆炸') || cmd.includes('explode')) {
            const matches = cmd.match(/\d+/);
            if (matches) {
                const val = Math.min(100, Math.max(0, parseInt(matches[0]))) / 100;
                handleUpdateItem(firstItem.id, { explodeFactor: val });
                commit(items.map(it => it.id === firstItem.id ? { ...it, explodeFactor: val } : it));
            }
            return;
        }

        try {
            const result = await parseModelSemanticCommand(fullCmd, firstItem.partList || []);
            const updates: Partial<CanvasItem> = {};

            if (result.action === 'paint' && result.targets) {
                const currentCMF = firstItem.partCMFMap || {};
                const newCMF = { ...currentCMF };
                const modelParts = firstItem.partList || [];

                result.targets.forEach((targetKeyword: string) => {
                    const matchedParts = modelParts.filter(p => 
                        p.toLowerCase().includes(targetKeyword.toLowerCase()) || 
                        targetKeyword.toLowerCase().includes(p.toLowerCase())
                    );

                    matchedParts.forEach(p => {
                        newCMF[p] = { 
                            color: result.params?.color,
                            metalness: result.params?.metalness,
                            roughness: result.params?.roughness,
                            emissiveIntensity: result.params?.emissiveIntensity || 0
                        };
                    });
                });
                updates.partCMFMap = newCMF;
                const matchedHighLights: string[] = [];
                result.targets.forEach((tk: string) => {
                    matchedHighLights.push(...modelParts.filter(p => p.toLowerCase().includes(tk.toLowerCase())));
                });
                updates.highlightedPartIds = matchedHighLights;

            } else if (result.action === 'highlight') {
                const modelParts = firstItem.partList || [];
                const matchedHighLights: string[] = [];
                result.targets.forEach((tk: string) => {
                    matchedHighLights.push(...modelParts.filter(p => p.toLowerCase().includes(tk.toLowerCase())));
                });
                updates.highlightedPartIds = matchedHighLights;
            } else if (result.action === 'explode') {
                updates.explodeFactor = result.params?.explodeFactor;
            } else if (result.action === 'view' && result.params?.spatialConfig) {
                updates.spatialConfig = result.params.spatialConfig;
                updates.cameraMode = 'orthographic';
            } else if (result.action === 'reset') {
                updates.partCMFMap = {};
                updates.highlightedPartIds = [];
                updates.explodeFactor = 0;
            }

            setItems(prev => prev.map(it => it.id === firstItem.id ? { ...it, ...updates } : it));
            commit(items.map(it => it.id === firstItem.id ? { ...it, ...updates } : it));

            console.log(`[ModelOS Feedback]: ${result.feedback}`);
        } catch (e) {
            console.error("Semantic command failed", e);
        }
        return;
    }

    switch(action) {
      case 'redo': {
        if (lastGenerationRef.current) {
          const { id: gid, prompt: gprompt, settings: gsettings, refs: grefs } = lastGenerationRef.current;
          handleGenerate(gid, gprompt, gsettings, grefs);
        } else if (firstItem.prompt) {
          handleGenerate(firstItem.id, firstItem.prompt);
        }
        break;
      }
      case 'extract_recipe': {
          const imageItems = currentSelectedItems.filter(it => it.type === ItemType.IMAGE && it.content);
          if (imageItems.length < 1) { alert("请至少选择一张图片来提取食谱。"); return; }
          setIsExtractingRecipe(true);
          try {
              const images = imageItems.map(it => it.content);
              const logic = await extractDesignRecipe(images, 0); 
              setRecipePanelData({ images, instruction: logic });
          } catch (e) { alert("食谱提取失败，请重试。"); } finally { setIsExtractingRecipe(false); }
          break;
      }
      case 'evolve': 
        handleGenerate(firstItem.id, `__EVOLUTION__|${currentEvolutionLevel}${isCncMode ? '|CNC' : ''}`); 
        setExpressionState({ itemId: '', isOpen: false });
        break;
      case 'expression': setExpressionState({ itemId: firstItem.id, isOpen: true }); break;
      case 'inference': setInferenceState({ itemId: firstItem.id, isOpen: true }); break;
      case 'variation': handleGenerate(firstItem.id, '[ACTION: VARIATION]'); break;
      case 'remove_bg': handleGenerate(firstItem.id, 'Remove background'); break;
      case 'upscale': handleGenerate(firstItem.id, 'UPSCALE TO 4K', { resolution: '4K', usePro: true }); break;
      case 'edit': setEditMode(true); setIsPropertiesPanelOpen(true); break;
      case 'delete': handleDeleteItems(selection); break;
      case 'copy': handleCopy(firstItem.id); break;
      case 'download': handleDownloadAsset(firstItem.id); break;
      case 'part_knolling': {
          if (firstItem.type !== ItemType.MODEL) return;
          const snapshot = captureModelSnapshot(firstItem.id);
          const partsStr = firstItem.partList?.join(', ') || "internal mechanical parts, sensors, and structural components";
          const knollingPrompt = `Professional industrial design knolling photography. Neatly arranged individual components of a ${firstItem.content || 'product'}: ${partsStr}. Consistent studio lighting, top-down orthographic view, components laid out in a perfect grid on a clean white technical background. Material semantics consistent with the master product. High precision CMF.`;
          handleGenerate(firstItem.id, knollingPrompt, { ratio: '16:9' }, snapshot ? [snapshot] : []);
          break;
      }
      case 'auto_staging': {
          if (firstItem.type !== ItemType.MODEL || !firstItem.modelUrl) return;
          const gap = 40;
          const size = firstItem.width;
          const startX = firstItem.x;
          const startY = firstItem.y;

          const stagingConfigs: { angle: any, x: number, y: number, spatial: SpatialConfig }[] = [
            { angle: 'top', x: startX + size + gap, y: startY, spatial: { azimuth: 0, elevation: 89, distance: 12, fov: 45 } },
            { angle: 'front', x: startX, y: startY + size + gap, spatial: { azimuth: 0, elevation: 0, distance: 12, fov: 45 } },
            { angle: 'side', x: startX + size + gap, y: startY + size + gap, spatial: { azimuth: 90, elevation: 0, distance: 12, fov: 45 } },
          ];

          const newItems = stagingConfigs.map(cfg => ({
            ...firstItem,
            id: crypto.randomUUID(),
            x: cfg.x,
            y: cfg.y,
            viewAngle: cfg.angle,
            cameraMode: 'orthographic' as const,
            spatialConfig: cfg.spatial,
            explodeFactor: firstItem.explodeFactor || 0,
          })) as CanvasItem[];

          const nextItems = [...items, ...newItems];
          setItems(nextItems);
          commit(nextItems);
          setSelection([firstItem.id, ...newItems.map(n => n.id)]);
          break;
      }
    }
  };

