      const mediaRecorder = new MediaRecorder(stream); mediaRecorderRef.current = mediaRecorder;
      mediaRecorder.ondataavailable = (event) => { if (event.data.size > 0) recordedChunksRef.current.push(event.data); };
      mediaRecorder.onstop = () => { const blob = new Blob(recordedChunksRef.current, { type: 'video/webm' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `无限想象-${Date.now()}.webm`; a.click(); setRecordingStatus('idle'); setRecordingTime(0); if (timerRef.current) window.clearInterval(timerRef.current); };
      mediaRecorder.start(); setRecordingStatus('recording'); timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000);
