          const padding = 40;
          const newFrame: CanvasItem = {
              id: crypto.randomUUID(),
              type: ItemType.FRAME,
              x: minX - padding,
              y: minY - padding,
              width: (maxX - minX) + padding * 2,
              height: (maxY - minY) + padding * 2,
              rotation: 0,
              content: '新组合画框',
              status: 'empty'
          };
          const nextItems = [...items, newFrame];
          setItems(nextItems); commit(nextItems); setSelection([newFrame.id]);
      } else if (action === 'gridify' && selected.length > 0) {
          const sorted = [...selected].sort((a, b) => a.y - b.y || a.x - b.x);
          const cols = Math.ceil(Math.sqrt(sorted.length));
          const gap = 40;
          const startX = Math.min(...selected.map(i => i.x));
          const startY = Math.min(...selected.map(i => i.y));
          const itemW = 512, itemH = 512;

          const updates = sorted.map((it, nid) => {
              const r = Math.floor(nid / cols), c = nid % cols;
              return { id: it.id, updates: { x: startX + c * (itemW + gap), y: startY + r * (itemH + gap), width: itemW, height: itemH } };
          });
          handleUpdateItems(updates);
          commit(items.map(it => {
              const u = updates.find(up => u.id === it.id);
              return u ? { ...it, ...u.updates } : it;
          }));
      } else if (action === 'delete') {
          handleDeleteItems(selection);
      } else if (action === 'copy') {
          handleCopy(null);
      } else if (action === 'send_to_gemini') {
          const item = items.find(i => i.id === itemId);
          if (item?.content) chatRef.current?.addExternalAttachment(item.id, item.content);
      } else if (action === 'send_to_prompt') {
          const item = items.find(i => i.id === itemId);
          if (item?.content) setExternalRefImage(item.content);
      }
      setContextMenu(null);
  };

  const executeCaptureAction = async (action: 'chat' | 'canvas' | 'translate') => {
      if (!captureRect) return;
      let finalImg = capturedImage;
      if (!finalImg) {
