  onExitEditMode?: () => void;
  initialView?: {view: string, ts: number} | null;
  onSendToPrompt?: (id: string) => void;
  onSendToGemini?: (id: string) => void;
  onSyncPointsToGemini?: (id: string) => void;
  onFrameAction?: (id: string, action: 'merge' | 'expand' | 'crop') => void;
