         <div className="text-center space-y-6">
            <div className="w-16 h-16 bg-zinc-800/50 rounded-[20px] flex items-center justify-center mx-auto border border-zinc-700/50">
                <SparklesIcon className="w-8 h-8 text-indigo-400 opacity-50" />
            </div>
            <div className="space-y-2">
                <h3 className="font-black text-white text-[12px] uppercase tracking-[0.2em]">工作台</h3>
                <p className="text-[11px] text-zinc-500 leading-relaxed max-w-[180px] mx-auto">选择一个画框、图像或 3D 模型来编辑其属性、生成变体或应用空间控制。</p>
            </div>
         </div>
      </div>
    );
  }

  const handleBack = () => {
    setCurrentView('main');
    onExitEditMode?.();
  };

  const renderModelPanel = () => {
    if (!selectedItem || selectedItem.type !== ItemType.MODEL) return null;

    const handleCaptureView = () => {
        if (!selectedItem.spatialConfig) return;
        const currentViews = selectedItem.savedViews || [];
        onUpdateItem(selectedItem.id, { 
            savedViews: [...currentViews, { ...selectedItem.spatialConfig }] 
        });
    };

    const handleApplyStandardView = (viewAngle: string, config: any) => {
        onUpdateItem(selectedItem.id, { 
            viewAngle: viewAngle as any, 
            spatialConfig: config,
            cameraMode: 'orthographic' // 标准视图强制使用正交相机
        });
    };

    const handleExecuteModelCommand = () => {
        if (!modelCommand.trim()) return;
        onFloatingAction?.(selectedItem.id, `model_cmd:${modelCommand}`);
        setModelCommand('');
    };

    const standardViews = [
        { id: 'front', label: '正 (Front)', config: { azimuth: 0, elevation: 0, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'side', label: '侧 (Side)', config: { azimuth: 90, elevation: 0, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'top', label: '顶 (Top)', config: { azimuth: 0, elevation: 89, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
        { id: 'perspective', label: '透 (Iso)', config: { azimuth: 45, elevation: 35, distance: selectedItem.spatialConfig?.distance || 12, fov: 45 } },
    ];

    return (
        <div className="flex flex-col h-full bg-[#09090b] text-white p-6 overflow-y-auto no-scrollbar pointer-events-auto space-y-8">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <BoxIcon className="w-5 h-5 text-indigo-500"/>
                    <span className="font-black text-[11px] uppercase tracking-[0.2em] text-zinc-100">3D 对象编排器</span>
                </div>
                <button onClick={() => onDelete(selectedItem.id)} className="w-8 h-8 flex items-center justify-center rounded-lg hover:bg-red-500/10 text-zinc-500 hover:text-red-500 transition-all">
                    <TrashIcon className="w-4 h-4"/>
                </button>
            </div>

            {/* 相机模式切换 */}
            <div className="space-y-3">
                <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                    <EyeIcon className="w-3.5 h-3.5" /> Camera Projection
                </label>
                <div className="flex bg-zinc-800/50 p-1 rounded-xl gap-1 border border-white/5">
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { cameraMode: 'perspective' })}
                        className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${selectedItem.cameraMode !== 'orthographic' ? 'bg-indigo-600 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
                    >
                        透视 (Persp)
                    </button>
                    <button 
                        onClick={() => onUpdateItem(selectedItem.id, { cameraMode: 'orthographic' })}
                        className={`flex-1 py-2 text-[10px] font-black uppercase tracking-widest rounded-lg transition-all ${selectedItem.cameraMode === 'orthographic' ? 'bg-indigo-600 text-white shadow-lg' : 'text-zinc-500 hover:text-zinc-300'}`}
                    >
                        正交 (Ortho)
                    </button>
                </div>
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                        <TerminalIcon className="w-3.5 h-3.5 text-indigo-400" /> Model Command Center
                    </label>
                </div>
                <div className="relative group">
                    <textarea 
                        value={modelCommand}
                        onChange={(e) => setModelCommand(e.target.value)}
                        onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleExecuteModelCommand(); } }}
                        className="w-full bg-[#111113] border border-zinc-800 rounded-xl px-4 py-3 text-[12px] h-20 focus:border-indigo-500/50 outline-none resize-none transition-all placeholder:text-zinc-700"
                        placeholder="输入指令: '喷涂零件红色' 或 '高亮指示灯'..."
                    />
                    <button 
                        onClick={handleExecuteModelCommand}
                        className="absolute bottom-2 right-2 p-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-lg transition-all shadow-lg active:scale-95"
                    >
                        <ArrowIcon className="w-3.5 h-3.5" />
                    </button>
                </div>
            </div>

            <div className="space-y-4">
                <div className="flex items-center justify-between">
                    <label className="text-[10px] font-black text-zinc-500 uppercase tracking-widest flex items-center gap-2">
                        <CameraIcon className="w-3.5 h-3.5" /> Perspective Manager
                    </label>
                    <button 
                        onClick={handleCaptureView}
                        className="p-1.5 bg-indigo-500/10 text-indigo-400 hover:bg-indigo-500/20 rounded-lg border border-indigo-500/20 transition-all"
                        title="捕获自定义视角"
                    >
                        <PlusIcon className="w-3.5 h-3.5" />
                    </button>
                </div>

                <div className="grid grid-cols-2 gap-2">
                    {standardViews.map(sv => (
                        <button 
                            key={sv.id}
                            onClick={() => handleApplyStandardView(sv.id, sv.config)}
                            className={`py-2.5 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all active:scale-95 ${selectedItem.viewAngle === sv.id ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-zinc-800/50 border-white/5 text-zinc-500 hover:bg-zinc-700 hover:text-white'}`}
                        >
                            {sv.label}
                        </button>
                    ))}
                </div>

                <div className="h-px bg-white/5 my-2" />

                <div className="grid grid-cols-4 gap-2">
                    {selectedItem.savedViews?.map((v, i) => (
                        <button 
