                                                </div>
                                                <button onClick={() => onUpdatePoint?.(targetImg.id, p.id, { pairingId: undefined, pairingSourceItemId: undefined })} className="p-1 text-zinc-600 hover:text-red-400 transition-colors ml-2 shrink-0">
