                                                </button>
                                            </div>
                                        ) : (
                                            <div className="flex-1 py-3 text-[10px] font-black text-zinc-700 uppercase tracking-widest border border-dashed border-zinc-800/50 rounded-xl text-center">
                                                等待配对...
                                            </div>
                                        )}
                                    </div>
                                </div>
                            );
