    const newItems = [...items, newItem];
    setItems(newItems); commit(newItems); setSelection([newItem.id]); centerOnItem(newItem);
  }, [items, findPlacementSpot, getImageDimensions, commit, setItems, setSelection, centerOnItem]);

  /**
   * 分离图层核心逻辑
   */
  const handleExplodeLayers = async (itemId: string) => {
    const item = items.find(i => i.id === itemId);
    if (!item || !item.content) return;

    setIsAnalyzingJSON(true);
    // 立即标记原始图层正在加载，给用户反馈
    handleUpdateItem(itemId, { status: 'loading' });

    try {
        // 1. 语义分割：获取零件 BBox
        const result = await detectImageJSONSegments(item.content);
        if (!result.segments || result.segments.length === 0) {
            alert("未能识别到足够的独立组件。");
            handleUpdateItem(itemId, { status: 'generated' });
            return;
        }

        // 2. 准备背景修复掩码 (1024x1024)
        const maskCanvas = document.createElement('canvas');
        maskCanvas.width = 1024; maskCanvas.height = 1024;
        const mCtx = maskCanvas.getContext('2d')!;
        mCtx.fillStyle = 'black'; mCtx.fillRect(0, 0, 1024, 1024);
        mCtx.fillStyle = 'white';
        result.segments.forEach((seg: any) => {
            const [ymin, xmin, ymax, xmax] = seg.box_2d;
            // 归一化坐标转换
            mCtx.fillRect(xmin * 1.024, ymin * 1.024, (xmax - xmin) * 1.024, (ymax - ymin) * 1.024);
        });
        const combinedMask = maskCanvas.toDataURL('image/png');

        // 3. 并行执行：AI 背景修复 + 前端资产切片
        const [inpaintedBase64, ...partAssets] = await Promise.all([
            inpaintBackground(item.content, combinedMask, item.aspectRatio || '1:1'),
            ...result.segments.map((seg: any): Promise<{base64: string, seg: any}> => {
                return new Promise((resolve) => {
                    const img = new Image();
                    img.crossOrigin = "anonymous";
                    img.onload = () => {
                        const [ymin, xmin, ymax, xmax] = seg.box_2d;
                        const pX = (xmin / 1000) * img.width;
                        const pY = (ymin / 1000) * img.height;
                        const pW = ((xmax - xmin) / 1000) * img.width;
                        const pH = ((ymax - ymin) / 1000) * img.height;

                        const pCanvas = document.createElement('canvas');
                        pCanvas.width = pW; pCanvas.height = pH;
                        const pCtx = pCanvas.getContext('2d')!;
                        pCtx.drawImage(img, pX, pY, pW, pH, 0, 0, pW, pH);
                        resolve({ base64: pCanvas.toDataURL('image/png'), seg });
                    };
                    img.src = item.content!;
                });
            })
        ]);

        // 4. 构建画框内的新项目
        const frameId = crypto.randomUUID();
        const padding = 60;

        // 底层背景
        const bgItem: CanvasItem = {
            id: crypto.randomUUID(),
            type: ItemType.IMAGE,
            x: item.x,
            y: item.y,
            width: item.width,
            height: item.height,
            rotation: 0,
            content: inpaintedBase64,
            status: 'generated',
            isChild: true,
            prompt: "Clean Background"
        };

        // 零件图层
        const layerItems: CanvasItem[] = partAssets.map(({ base64, seg }) => {
            const [ymin, xmin, ymax, xmax] = seg.box_2d;
            return {
                id: crypto.randomUUID(),
                type: ItemType.IMAGE,
                x: item.x + (xmin / 1000) * item.width,
                y: item.y + (ymin / 1000) * item.height,
                width: ((xmax - xmin) / 1000) * item.width,
                height: ((ymax - ymin) / 1000) * item.height,
                rotation: 0,
                content: base64,
                status: 'generated',
                prompt: seg.label,
                isChild: true
            };
        });

        // 顶层画框
        const frame: CanvasItem = {
            id: frameId,
            type: ItemType.FRAME,
            x: item.x - padding/2,
            y: item.y - padding/2,
            width: item.width + padding,
            height: item.height + padding,
            rotation: 0,
            content: `Exploded: ${segLabels(result.segments)}`,
            status: 'generated'
        };

        // 5. 替换旧项目并提交历史
        const nextItems = items.filter(i => i.id !== item.id);
        const finalItems = [...nextItems, frame, bgItem, ...layerItems];
        setItems(finalItems);
        commit(finalItems);
        setSelection([frameId]);

    } catch (e) {
        console.error("Explode layers process failed:", e);
        alert("图层分离异常，请确保网络通畅并重试。");
        handleUpdateItem(itemId, { status: 'generated' });
    } finally {
        setIsAnalyzingJSON(false);
    }
  };

  const segLabels = (segs: any[]) => segs.slice(0, 3).map(s => s.label).join(', ') + (segs.length > 3 ? '...' : '');

  const handlePickPoint = async (itemId: string, y: number, x: number) => {
    const item = items.find(i => i.id === itemId);
    if (!item || !item.content) return;
    if (tool === 'point') {
        let max = 0;
        items.forEach(it => it.identifiedPoints?.forEach(p => { const num = parseInt(p.label, 10); if (!isNaN(num) && num > max) max = num; }));
        const nextLabel = (max + 1).toString();
        const newPoint: IdentifiedPoint = { id: crypto.randomUUID(), y, x, label: nextLabel };
        const nextItems = items.map(it => it.id === itemId ? { ...it, identifiedPoints: [...(it.identifiedPoints || []), newPoint] } : it);
        setItems(nextItems); commit(nextItems);
        chatRef.current?.addPointReference(itemId, item.content, nextLabel, [y, x]);
        return;
    }
    try {
        const aiLabel = await identifyPoint(item.content, y, x);
        let max = 0;
        items.forEach(it => it.identifiedPoints?.forEach(p => { const num = parseInt(p.label, 10); if (!isNaN(num) && num > max) max = num; }));
        const nextLabel = (max + 1).toString();
        const newPoint: IdentifiedPoint = { id: crypto.randomUUID(), y, x, label: nextLabel, description: aiLabel };
        const nextItems = items.map(it => it.id === itemId ? { ...it, identifiedPoints: [...(it.identifiedPoints || []), newPoint] } : it);
        setItems(nextItems); commit(nextItems);
        chatRef.current?.addPointReference(itemId, item.content, nextLabel, [y, x]);
    } catch (e) { console.error(e); }
  };

  const handleGenerate = async (id: string, overridePrompt?: string, settings?: Partial<GenerationSettings>, manualRefs?: string[]) => {
    const rawPrompt = overridePrompt || (items.find(i => i.id === id)?.prompt || "Professional design");
    if (rawPrompt === '__START_PICK_POINT__') { 
        const item = items.find(i => i.id === id); if (!item || !item.content) return;
        setIsPickingPoint(true); setPickingTargetId(id);
        try {
            const rawPoints = await detectAllPoints(item.content, settings?.artisticLevel || 0.8);
            setItems(prev => {
                let currentGlobalMax = 0;
                prev.forEach(it => it.identifiedPoints?.forEach(p => { const num = parseInt(p.label, 10); if (!isNaN(num) && num > currentGlobalMax) currentGlobalMax = num; }));
                const newIdentifiedPoints: IdentifiedPoint[] = rawPoints.map((p, idx) => ({ id: crypto.randomUUID(), y: p.point[0], x: p.point[1], label: (currentGlobalMax + idx + 1).toString(), description: p.label }));
                const nextItems = prev.map(it => it.id === id ? { ...it, identifiedPoints: [...(it.identifiedPoints || []), ...newIdentifiedPoints] } : it);
                if (chatRef.current) chatRef.current.addBulkPointReferences(id, item.content!, rawPoints.map((p, idx) => ({ label: (currentGlobalMax + idx + 1).toString(), point: p.point })));
                return nextItems;
            });
            commit(items);
        } finally { setIsPickingPoint(false); setPickingTargetId(null); }
        return; 
    }

    lastGenerationRef.current = { id, prompt: overridePrompt, settings, refs: manualRefs };
    const sourceItem = id ? items.find(i => i.id === id) : null; 
    let contextItem: CanvasItem | null = id ? (sourceItem || null) : null;
    const { tasks, isEvolution, level } = parseGenerationIntent(rawPrompt, contextItem, settings);
    if (isEvolution && level !== undefined) setCurrentEvolutionLevel(level);

    let targetW = 512, targetH = 512; 
    let ratioToUse = settings?.ratio || '1:1';
    if (contextItem) { targetW = contextItem.width; targetH = contextItem.height; ratioToUse = contextItem.aspectRatio || ratioToUse; } 
    else if (manualRefs && manualRefs.length > 0) { const dims = await getImageDimensions(manualRefs[0]); targetW = dims.width; targetH = dims.height; ratioToUse = getClosestAspectRatio(dims.width, dims.height); } 
    else { const ratioObj = ASPECT_RATIOS.find(r => r.id === ratioToUse) || ASPECT_RATIOS[0]; targetW = ratioObj.width; targetH = ratioObj.height; }

    const styleId = settings?.style || 'industrial'; 
    const styleObj = STYLES.find(s => s.id === styleId) || STYLES[1];
    let recipeTxt = "";
    if (settings?.recipeId) { const allR = await getAllRecipes(); recipeTxt = allR.find(r => r.id === settings.recipeId)?.instruction || ""; }

    const placeholderItems: CanvasItem[] = tasks.map((t, idx) => {
        const spot = findPlacementSpot(targetW, targetH, items, sourceItem || undefined, idx);
        return { id: t.nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: targetW, height: targetH, rotation: 0, content: '', status: 'loading', prompt: t.prompt, style: styleId, aspectRatio: ratioToUse };
    });
    setItems(prev => [...prev, ...placeholderItems]);

    for (const task of tasks) {
        try {
            let url: string;
            if (task.infCfg) {
                const refs = manualRefs ? manualRefs.map((r, i) => ({ label: `Ref ${i+1}`, base64: r })) : (contextItem?.content ? [{ label: 'Base', base64: contextItem.content }] : []);
                url = await generateWithReferences(task.prompt, refs, ratioToUse, styleObj.promptSuffix, settings?.artisticLevel || 50, '1K', settings?.spatialConfig, recipeTxt, task.infCfg, settings?.usePro);
            } else if (task.prompt === '__VISUAL_PEEL__' && contextItem?.content) {
                url = await generateVisualPeel(contextItem.content, ratioToUse, settings?.usePro);
            } else if (task.prompt.startsWith('__TOPOLOGY_VAR__') && contextItem?.content) {
                url = await generateTopologyVariation(contextItem.content, ratioToUse, styleObj.promptSuffix, settings?.usePro);
            } else if (manualRefs && manualRefs.length > 0) {
                url = await generateWithReferences(task.prompt, manualRefs.map((r, i) => ({ label: `Ref ${i+1}`, base64: r })), ratioToUse, styleObj.promptSuffix, settings?.artisticLevel || 50, '1K', undefined, recipeTxt, undefined, settings?.usePro);
            } else {
                url = await generateImage(task.prompt, styleObj.promptSuffix, ratioToUse, settings?.artisticLevel || 50, '1K', undefined, recipeTxt, settings?.usePro);
            }
            handleUpdateItem(task.nid, { content: url, status: 'generated' });
        } catch (e) { handleUpdateItem(task.nid, { status: 'error' }); }
    }
    commit(items);
  };

  const handleFrameAction = async (id: string, action: 'merge' | 'expand' | 'crop') => {
    const frame = items.find(i => i.id === id);
    if (!frame) return;
    const children = items.filter(it => it.id !== id && it.x >= frame.x && it.x + it.width <= frame.x + frame.width && it.y >= frame.y && it.y + it.height <= frame.y + frame.height && it.type === ItemType.IMAGE && it.content);
    if (children.length === 0 && action === 'merge') return;

    if (action === 'merge') {
        const nid = crypto.randomUUID();
        const spot = { x: frame.x, y: frame.y };
        setItems(prev => [...prev, { id: nid, type: ItemType.IMAGE, x: spot.x, y: spot.y, width: frame.width, height: frame.height, rotation: 0, content: '', status: 'loading', prompt: frame.prompt, aspectRatio: getClosestAspectRatio(frame.width, frame.height) }]);
        try {
            const refs = children.map((c, i) => ({ label: `Element ${i+1}`, base64: c.content }));
            const url = await generateWithReferences(frame.prompt || "A professionally merged industrial design scene, consistent lighting and shadows", refs, getClosestAspectRatio(frame.width, frame.height), STYLES[1].promptSuffix);
            handleUpdateItem(nid, { content: url, status: 'generated' });
            commit(items);
        } catch (e) { handleUpdateItem(nid, { status: 'error' }); }
    } else if (action === 'expand') {
        const nid = crypto.randomUUID();
        const mainChild = children[0];
        if (!mainChild) return;
        setItems(prev => [...prev, { id: nid, type: ItemType.IMAGE, x: frame.x, y: frame.y, width: frame.width, height: frame.height, rotation: 0, content: '', status: 'loading', prompt: frame.prompt, aspectRatio: getClosestAspectRatio(frame.width, frame.height) }]);
        try {
            const url = await editImage(mainChild.content, "Outpaint and expand the scene to fill the frame, maintain consistency", getClosestAspectRatio(frame.width, frame.height));
            handleUpdateItem(nid, { content: url, status: 'generated' });
            commit(items);
        } catch (e) { handleUpdateItem(nid, { status: 'error' }); }
    }
  };

  const handleFloatingAction = (id: string, action: string) => {
    const item = items.find(it => it.id === id);
    if (!item) return;
    if (action === 'delete') handleDeleteItems(selection);
    else if (action === 'copy') handleCopy(id);
    else if (action === 'upscale') handleGenerate(id, "UPSCALE TO 4K", { resolution: '4K', usePro: true });
    else if (action === 'remove_bg') handleGenerate(id, "Remove background, isolated on white", { artisticLevel: 0 });
    else if (action === 'variation') handleGenerate(id, "__TOPOLOGY_VAR__");
    else if (action === 'redo') { if (lastGenerationRef.current) handleGenerate(lastGenerationRef.current.id, lastGenerationRef.current.prompt, lastGenerationRef.current.settings, lastGenerationRef.current.refs); else handleGenerate(id); }
    else if (action === 'edit') { setEditMode(true); setIsPropertiesPanelOpen(true); }
    else if (action === 'expression') setExpressionState({ itemId: id, isOpen: true });
    else if (action === 'inference') setInferenceState({ itemId: id, isOpen: true });
    else if (action === 'evolve') setIsPropertiesPanelOpen(true);
    else if (action.startsWith('expr:')) handleGenerate(id, action.split(':')[1], { artisticLevel: 100 });
    else if (action.startsWith('evolve_with_level:')) handleGenerate(id, `__EVOLUTION__|${action.split(':')[1]}|${isCncMode ? 'CNC' : ''}`);
    else if (action.startsWith('inference:')) { const [_, data] = action.split(':'); handleGenerate(id, `inference:${data}`); }
    else if (action === 'extract_recipe') {
        const selectedImages = items.filter(it => selection.includes(it.id) && it.type === ItemType.IMAGE && it.content);
        if (selectedImages.length > 0) {
            setIsExtractingRecipe(true);
            extractDesignRecipe(selectedImages.map(img => img.content)).then(instruction => {
                setRecipePanelData({ images: selectedImages.map(img => img.content), instruction });
            }).finally(() => setIsExtractingRecipe(false));
        }
    } else if (action.startsWith('model_cmd:')) {
        const cmd = action.split(':')[1];
        chatWithGemini(`[3D MODEL COMMAND] Context: This is a 3D model with parts: ${item.partList?.join(', ') || 'unknown'}. 
            Instruction: ${cmd}.
            Task: Assign colors or materials to specific parts. 
            Format: Return JSON object { "partCMFMap": { "part_name": { "color": "#hex", "metalness": 0.8, "roughness": 0.2 } } }`, 
            [], false, [], false
        ).then(res => {
            try {
                const match = res.match(/\{[\s\S]*\}/);
                if (match) {
                    const data = JSON.parse(match[0]);
                    if (data.partCMFMap) {
                        const currentMap = item.partCMFMap || {};
                        handleUpdateItem(id, { partCMFMap: { ...currentMap, ...data.partCMFMap } });
                    }
                }
            } catch(e) { console.error("Model command parse error", e); }
        });
    } else if (action === 'auto_staging') {
        const angles: ('front'|'side'|'top'|'perspective')[] = ['front', 'side', 'top', 'perspective'];
        angles.forEach((angle, idx) => {
            const angleConfigs: Record<string, SpatialConfig> = {
                front: { azimuth: 0, elevation: 0, distance: 12, fov: 45 },
                side: { azimuth: 90, elevation: 0, distance: 12, fov: 45 },
                top: { azimuth: 0, elevation: 89, distance: 12, fov: 45 },
                perspective: { azimuth: 45, elevation: 35, distance: 12, fov: 45 }
            };
            handleGenerate(id, `Industrial high-end render, ${angle} view`, { spatialConfig: angleConfigs[angle], usePro: true });
        });
    }
  };

  const handleCaptureRegion = async (region: Rect, action: 'chat' | 'canvas' | 'translate', capturedImage?: string | null, annos?: any[]) => {
      if (!capturedImage) return;
      if (action === 'canvas') { handleAddToCanvas(capturedImage, "Captured region"); } 
      else if (action === 'chat') { chatRef.current?.addExternalAttachment(id, capturedImage); }
      else if (action === 'translate') {
          const res = await chatWithGemini("Translate all text in this image to Chinese. Maintain the layout context.", [], true, [capturedImage]);
          alert(`翻译结果:\n\n${res}`);
      }
  };

  const handleSyncPointsToGemini = async (itemId: string) => {
    const item = items.find(i => i.id === itemId);
    if (!item || !item.content || !item.identifiedPoints?.length) return;
    const compressed = await compressImageForSync(item.content);
    chatRef.current?.addBulkPointReferences(itemId, compressed, item.identifiedPoints.map(p => ({ label: p.label, point: [p.y, p.x] })));
  };

  const handleAutoAlign = async (sourceId: string, targetId: string) => {
      const source = items.find(i => i.id === sourceId);
      const target = items.find(i => i.id === targetId);
      if (!source?.content || !target?.content || !source.identifiedPoints?.length || !target.identifiedPoints?.length) return;
      try {
          const res = await chatWithGemini(`Analyze these two industrial design images. 
          Source has points: ${source.identifiedPoints.map(p => `${p.label}(${p.description})`).join(', ')}.
          Target has points: ${target.identifiedPoints.map(p => `${p.label}(${p.description})`).join(', ')}.
          Task: Create a semantic mapping between Target points and Source points. 
          Return JSON: { "mappings": [ { "targetLabel": "1", "sourceId": "source_point_uuid" } ] }`, 
          [], false, [source.content, target.content]);

          const match = res.match(/\{[\s\S]*\}/);
          if (match) {
              const data = JSON.parse(match[0]);
              const newPoints = target.identifiedPoints.map(tp => {
                  const m = data.mappings.find((x: any) => x.targetLabel === tp.label);
                  if (m) {
                      const sp = source.identifiedPoints!.find(p => p.id === m.sourceId);
                      return sp ? { ...tp, pairingId: sp.id, pairingSourceItemId: sourceId } : tp;
                  }
                  return tp;
              });
              handleUpdateItem(targetId, { identifiedPoints: newPoints });
          }
      } catch (e) { console.error("Auto align failed", e); }
  };

  return (
    <div className="flex h-screen w-screen bg-[#f4f4f5] dark:bg-[#09090b] text-zinc-900 dark:text-zinc-100 overflow-hidden font-['Inter'] relative">
      <TopBar onExport={() => { const pkg: ProjectPackage = { version: '1.0', timestamp: Date.now(), items, view }; const blob = new Blob([JSON.stringify(pkg)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `imagination_project_${Date.now()}.json`; a.click(); }} onImport={async (file) => { const text = await file.text(); const pkg = JSON.parse(text) as ProjectPackage; resetHistory(pkg.items); setView(pkg.view); }} onCloudExport={async () => { await uploadProjectToCloud({ version: '1.0', timestamp: Date.now(), items, view }); }} onCloudImport={async () => { const pkg = await downloadProjectFromCloud(); resetHistory(pkg.items); setView(pkg.view); }} onNewProject={() => { if(confirm("确定要清空画布并开始新项目吗？")) { resetHistory([]); setView({ x: 0, y: 0, scale: 1 }); setSelection([]); } }} />

      <LeftToolbar activeTool={tool} setTool={setTool} onUpload={() => fileInputRef.current?.click()} onToggleLayers={() => setShowLayers(!showLayers)} showLayers={showLayers} onToggleHistory={() => setShowHistory(!showHistory)} showHistory={showHistory} recordingStatus={recordingStatus} onStartRecording={(res) => { setRecordingStatus('recording'); setRecordingTime(0); timerRef.current = window.setInterval(() => setRecordingTime(prev => prev + 1), 1000); }} onStopRecording={() => { setRecordingStatus('idle'); if(timerRef.current) clearInterval(timerRef.current); }} onPauseRecording={() => setRecordingStatus('paused')} onResumeRecording={() => setRecordingStatus('recording')} recordingTime={recordingTime} />

      <main className="flex-1 relative overflow-hidden bg-white dark:bg-black">
        <Canvas ref={canvasRef} items={items} selection={selection} tool={tool} view={view} setView={setView} setSelection={setSelection} addItem={(it) => { const next = [...items, it]; setItems(next); commit(next); }} updateItem={handleUpdateItem} updateItems={handleUpdateItems} onContextMenu={(e, itemId) => setContextMenu({ isOpen: true, x: e.clientX, y: e.clientY, itemId })} onDelete={handleDeleteItems} editMode={editMode} editTool={editTool} brushSize={brushSize} brushColor={brushColor} segments={segments} onApplyEdit={(p) => { canvasRef.current?.getMaskData().then(data => { if (data && selectedItem) handleGenerate(selectedItem.id, p, { artisticLevel: 0 }, [data.cutout]); setEditMode(false); canvasRef.current?.clearMask(); }); }} onSelectItem={(id) => { setSelection([id]); setIsPropertiesPanelOpen(true); }} onPointPicked={handlePickPoint} isPickingPoint={isPickingPoint} onPointTagClick={(it, pt) => chatRef.current?.addPointReference(it.id, it.content!, pt.label, [pt.y, pt.x])} showPointLabels={showPointLabels} onDeletePointLocal={(itemId, pointId) => { const it = items.find(i => i.id === itemId); if (it) handleUpdateItem(itemId, { identifiedPoints: it.identifiedPoints?.filter(p => p.id !== pointId) }); }} onMovePoint={(itemId, ptId, ny, nx) => { const it = items.find(i => i.id === itemId); if(it) handleUpdateItem(itemId, { identifiedPoints: it.identifiedPoints?.map(p => p.id === ptId ? { ...p, y: ny, x: nx } : p) }); }} onMovePointEnd={(itemId, ptId, from, to) => { const it = items.find(i => i.id === itemId); if(it && it.content) chatRef.current?.appendMovementDescription(itemId, it.content, it.identifiedPoints?.find(p => p.id === ptId)?.label || '?', from, to); }} showGrid={showGrid} onZoomToFit={zoomToFit} onCaptureRegion={handleCaptureRegion} onFloatingAction={handleFloatingAction} expressionState={expressionState} setExpressionState={setExpressionState} inferenceState={inferenceState} setInferenceState={setInferenceState} currentEvolutionLevel={currentEvolutionLevel} captureState={captureState} onExitToolMode={() => setTool('select')} activePartId={activePartId} onPartSelect={setActivePartId} onCameraChange={(id, spatial) => handleUpdateItem(id, { spatialConfig: spatial })} onLoadParts={(id, parts) => handleUpdateItem(id, { partList: parts })} />

        {isPropertiesPanelOpen && (
          <div className="absolute top-4 right-4 bottom-10 w-80 z-40 pointer-events-none">
            <PropertiesPanel selectedItem={selectedItem} selectedItems={selectedItems} onUpdateItem={handleUpdateItem} onGenerate={handleGenerate} onDelete={(id) => handleDeleteItems([id])} onAutoPrompt={async (id) => { const it = items.find(i => i.id === id); if (it?.content) { const p = await analyzeImageForPrompt(it.content); handleUpdateItem(id, { prompt: p }); } }} onEnterEditMode={(t) => { setEditMode(true); setEditTool(t); }} onExitEditMode={() => setEditMode(false)} onSendToPrompt={(id) => setExternalRefImage(items.find(i => i.id === id)?.content || null)} onSendToGemini={(id) => { const it = items.find(i => i.id === id); if (it?.content) chatRef.current?.addExternalAttachment(id, it.content); }} onSyncPointsToGemini={handleSyncPointsToGemini} onFrameAction={handleFrameAction} editTool={editTool} setEditTool={setEditTool} brushSize={brushSize} setBrushSize={setBrushSize} onApplyEdit={(p) => { canvasRef.current?.getMaskData().then(data => { if (data && selectedItem) handleGenerate(selectedItem.id, p, { artisticLevel: 0 }, [data.cutout]); setEditMode(false); canvasRef.current?.clearMask(); }); }} onClearMask={() => canvasRef.current?.clearMask()} onJSONAnalysis={handleExplodeLayers} isAnalyzingJSON={isAnalyzingJSON} onStartPickPoint={(id, temp) => handleGenerate(id, '__START_PICK_POINT__', { artisticLevel: temp })} isPickingPoint={isPickingPoint} currentEvolutionLevel={currentEvolutionLevel} isCncMode={isCncMode} setIsCncMode={setIsCncMode} onUpdatePoint={(itemId, ptId, up) => { const it = items.find(i => i.id === itemId); if(it) handleUpdateItem(itemId, { identifiedPoints: it.identifiedPoints?.map(p => p.id === ptId ? { ...p, ...up } : p) }); }} onClearAllPoints={(itemId) => handleUpdateItem(itemId, { identifiedPoints: [] })} onCommitPointChanges={(itemId) => { const it = items.find(i => i.id === itemId); if(!it) return; const pointsToRem = it.identifiedPoints?.filter(p => p.isRemoving).map(p => p.id) || []; const finalPoints = it.identifiedPoints?.filter(p => !p.isRemoving).map(p => ({ ...p, description: p.modifiedDescription || p.description, modifiedDescription: undefined })) || []; handleUpdateItem(itemId, { identifiedPoints: finalPoints }); commit(items); handleGenerate(itemId, `Semantic batch update based on ${finalPoints.length} points.`); }} onAutoAlign={handleAutoAlign} onClosePanel={() => setIsPropertiesPanelOpen(false)} onFloatingAction={handleFloatingAction} />
          </div>
        )}

        <LayersPanel isOpen={showLayers} items={items} selection={selection[0] || null} onSelectItem={(id) => { setSelection([id]); setIsPropertiesPanelOpen(true); }} onUpdateItem={handleUpdateItem} />

        <HistoryPanel isOpen={showHistory} onClose={() => setShowHistory(false)} onRestore={(snap) => { resetHistory(snap.items); setSelection([]); }} />

        <div className="absolute bottom-10 left-1/2 -translate-x-1/2 flex flex-col items-center gap-6 pointer-events-none w-full max-w-4xl px-10">
          <BottomBar lastGenerated={null} externalRef={externalRefImage} onExternalRefConsumed={() => setExternalRefImage(null)} onGenerate={(p, s, r, refs, count, art, res, rid, pro) => handleGenerate('', p, { style: s, ratio: r, imageCount: count, artisticLevel: art, resolution: res, recipeId: rid, usePro: pro }, refs)} onExportRecipes={() => { getAllRecipes().then(rs => { const blob = new Blob([JSON.stringify(rs)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = `design_recipes_${Date.now()}.json`; a.click(); }); }} onImportRecipes={(file) => { file.text().then(t => { const rs = JSON.parse(t) as DesignRecipe[]; rs.forEach(r => saveRecipe(r)); setRecipeRefreshTrigger(prev => prev + 1); }); }} />
        </div>

        <GeminiChatPanel ref={chatRef} onAddToCanvas={handleAddToCanvas} onReceiveSegments={(segs) => { setSegments(segs); }} />

        {contextMenu?.isOpen && (
          <ContextMenu x={contextMenu.x} y={contextMenu.y} selectedItem={contextMenu.itemId ? items.find(i => i.id === contextMenu.itemId) || null : null} isMulti={selection.length > 1} onClose={() => setContextMenu(null)} onSelect={(action) => {
            const itemId = contextMenu.itemId || selection[0];
            if (action === 'delete') handleDeleteItems(selection);
            else if (action === 'copy') handleCopy(itemId);
            else if (action === 'frame_selection') {
                const selectedOnes = items.filter(it => selection.includes(it.id));
                if (selectedOnes.length > 0) {
                    const minX = Math.min(...selectedOnes.map(it => it.x)), minY = Math.min(...selectedOnes.map(it => it.y));
                    const maxX = Math.max(...selectedOnes.map(it => it.x + it.width)), maxY = Math.max(...selectedOnes.map(it => it.y + it.height));
                    const padding = 40;
                    const frame: CanvasItem = { id: crypto.randomUUID(), type: ItemType.FRAME, x: minX - padding, y: minY - padding, width: (maxX - minX) + padding * 2, height: (maxY - minY) + padding * 2, rotation: 0, content: 'Selection Frame', status: 'generated' };
                    const next = [...items, frame]; setItems(next); commit(next);
                }
            } else if (action === 'variations') { if (itemId) handleGenerate(itemId, "__TOPOLOGY_VAR__"); }
            else if (action === 'send_to_gemini') { const it = items.find(i => i.id === itemId); if(it?.content) chatRef.current?.addExternalAttachment(itemId, it.content); }
            else if (action === 'send_to_prompt') { setExternalRefImage(items.find(i => i.id === itemId)?.content || null); }
            setContextMenu(null);
          }} />
        )}
      </main>

      {recipePanelData && (
        <DesignRecipePanel initialInstruction={recipePanelData.instruction} exampleImages={recipePanelData.images} onSave={(name, instr) => { saveRecipe({ id: crypto.randomUUID(), name, instruction: instr, exampleImages: recipePanelData.images, createdAt: Date.now() }); setRecipePanelData(null); setRecipeRefreshTrigger(prev => prev + 1); }} onClose={() => setRecipePanelData(null)} />
      )}

      {quickLookItem && (
        <div className="fixed inset-0 z-[1000] bg-black/90 backdrop-blur-3xl flex items-center justify-center p-20 animate-in fade-in duration-500" onClick={() => setQuickLookItem(null)}>
           <div className="relative max-w-full max-h-full group">
              <img src={quickLookItem.content} className="max-w-full max-h-[80vh] rounded-[40px] shadow-[0_80px_160px_rgba(0,0,0,1)] border border-white/10" />
              <div className="absolute -bottom-24 left-1/2 -translate-x-1/2 flex items-center gap-6 bg-zinc-900/80 backdrop-blur-xl px-10 py-5 rounded-full border border-white/10 shadow-2xl">
                 <button onClick={(e) => { e.stopPropagation(); handleDownloadAsset(quickLookItem.id); }} className="flex items-center gap-3 text-zinc-300 hover:text-white font-black uppercase tracking-widest text-[12px]"><DownloadIcon className="w-5 h-5"/> Download</button>
                 <div className="w-px h-6 bg-white/10" />
                 <button onClick={(e) => { e.stopPropagation(); handleCopy(quickLookItem.id); }} className="flex items-center gap-3 text-zinc-300 hover:text-white font-black uppercase tracking-widest text-[12px]"><CopyIcon className="w-5 h-5"/> Copy</button>
              </div>
           </div>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={(e) => { const file = e.target.files?.[0]; if (file) handleFile(file); e.target.value = ''; }} className="hidden" accept="image/*,.obj" />

      <style>{`
        @keyframes pulse-indigo { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
        .animate-pulse-subtle { animation: pulse-indigo 3s infinite ease-in-out; }
        .vertical-text { writing-mode: vertical-lr; text-orientation: mixed; }
        .custom-scrollbar::-webkit-scrollbar { width: 6px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #27272a; border-radius: 10px; }
      `}</style>
    </div>
  );
};

export default App;
